[Form]
public class ISDAppIntgDMFBulkUpdate extends FormRun
{
    DMFDefinitionGroupExecution     dmfDefGroupExecution;
    DMFSourceXMLToEntityMap         dmfSourceXMLToEntityMap;
    SysDictField                    dictField;
    DMFFieldType                    dmfFieldType;
    Types                           valueType;
    DMFEntity                       entity;
    FieldId                         defGroupFieldId,
                                    executionFieldId;
    FieldName                       fieldName;
    str                             fieldValue;
    Common                          common;

}

/// <summary>
/// Form init method
/// </summary>
public void init()
{
    Object  callerForm;

    super();

    if (element.args().record().TableId == tableNum(Common))
    {
        throw error(strfmt("@SYS25516", element.name()));
    }

    callerForm = element.args().caller();

    if (callerForm && formHasMethod(callerForm, identifierStr(dmfDefinitionGroupExecution)))
    {
        dmfDefGroupExecution = callerForm.dmfDefinitionGroupExecution();
    }

    if (element.args().record())
    {
        boolean isDataSelected;

        common = element.args().record();

        isDataSelected = ISDAppIntgDMFBulkUpdate::isDataSelected(common);

        if (!isDataSelected)
        {
            Box::warning("@DMF:DMFMultipleRecordsNotSelected");
            element.close();
        }
    }

    if (dmfDefGroupExecution)
    {
        select Entity, EntityField from dmfSourceXMLToEntityMap
            where dmfSourceXMLToEntityMap.DefinitionGroup == dmfDefGroupExecution.DefinitionGroup
               && dmfSourceXMLToEntityMap.Entity          == dmfDefGroupExecution.Entity;
    }
}

/// <summary>
/// Update form controls
/// </summary>
public void updateControl()
{
    #define.Integer('Integer')
    #define.String('String')
    #define.RealMacro('Real')
    #define.DateMacro('Date')
    #define.DateTimeMacro('UtcDateTime')
    #define.Time('Time')

    DMFDefinitionGroupEntityXMLFields   dmfDefinitionGroupEntityXMLFields;

    void resetOriginal()
    {
        StagingIntValue.visible(false);
        StagingStrValue.visible(false);
        StagingRealValue.visible(false);
        StagingDateValue.visible(false);
        StagingUtcDataTime.visible(false);
        StagingTimeValue.visible(false);
    }

    select firstOnly FieldType from dmfDefinitionGroupEntityXMLFields
    where dmfDefinitionGroupEntityXMLFields.FieldName == element.parmStagingField();

    if (dmfDefinitionGroupEntityXMLFields.FieldType)
    {
        dmfFieldType = dmfDefinitionGroupEntityXMLFields.FieldType;
        if (dmfsourceXMLToEntityMap.EntityField)
        {
            entity = DMFEntity::find(dmfsourceXMLToEntityMap.Entity);
            dictField = new SysDictField(tableName2id(entity.EntityTable), fieldName2id(tableName2Id(entity.EntityTable),dmfsourceXMLToEntityMap.EntityField));
        }
        resetOriginal();
        switch(dmfDefinitionGroupEntityXMLFields.FieldType)
        {
            case #Integer:
                StagingIntValue.visible(true);
                break;
            case #String:
                StagingStrValue.visible(true);
                break;
            case #RealMacro:
                StagingRealValue.visible(true);
                break;
            case #DateMacro:
                StagingDateValue.visible(true);
                break;
            case #DateTimeMacro:
                StagingUtcDataTime.visible(true);
                break;
            case #Time:
                StagingTimeValue.visible(true);
                break;
            default:
                warning("@DMF694");
        }
    }
}

/// <summary>
/// Return source name 
/// </summary>
/// <param name = "_fieldName">Field name</param>
/// <returns>DMFSourceName</returns>
public DMFSourceName parmStagingField(FieldName _fieldName = fieldName)
{
    fieldName = _fieldName;

    return fieldName;
}

/// <summary>
/// Field value
/// </summary>
/// <param name = "_fieldValue">field value</param>
/// <returns> Field value</returns>
public anytype parmStagingValue(anytype  _fieldValue = fieldValue)
{
    fieldValue = _fieldValue;

    return fieldValue;
}

/// <summary>
/// Lookup method
/// </summary>
public void lookup()
{
    SysTableLookup          tableLookup;
    QueryBuildDataSource    qbd;
    Query                   query = new Query();
    QueryBuildRange         queryBuildRange; 

    tableLookup = SysTableLookup::newParameters(tableNum(DMFSourceXMLToEntityMap), this);

    tableLookup.addLookupfield(fieldNum(DMFSourceXMLToEntityMap, EntityField));
    tableLookup.addLookupMethod(tableMethodStr(DMFSourceXMLToEntityMap, labelLookUp));
    tableLookup.setLabel("Label");
    tableLookup.addLookupMethod(tableMethodStr(DMFSourceXMLToEntityMap, helpTextLookUp));
    tableLookup.setLabel("Help Text");

    qbd = query.addDataSource(tableNum(DMFSourceXMLToEntityMap));
    queryBuildRange = qbd.addRange(fieldNum(DMFSourceXMLToEntityMap,DefinitionGroup));
    queryBuildRange.value(queryValue(dmfDefGroupExecution.DefinitionGroup));

    queryBuildRange = qbd.addRange(fieldNum(DMFSourceXMLToEntityMap,Entity));
    queryBuildRange.value(queryValue(dmfDefGroupExecution.Entity));

    queryBuildRange = qbd.addRange(fieldNum(DMFSourceXMLToEntityMap, EntityField));
    queryBuildRange.value(SysQuery::valueNotEmptyString());

    tableLookup.parmQuery(query);
    tableLookup.performFormLookup();
}

/// <summary>
/// Validate method
/// </summary>
/// <returns>Boolean</returns>
public boolean validate()
{
    DMFSourceXMLToEntityMap sourceXMLToEntityMap;
    boolean                 ret;

    ret = super();

    if (ret)
    {
        select firstonly EntityField from sourceXMLToEntityMap
            where sourceXMLToEntityMap.EntityField == this.valueStr();

        if(!sourceXMLToEntityMap)
        {
            ret = checkFailed(strFmt("@DMF191" + ' ' + "@GLS94031", this.valueStr()));
            this.text('');
        }

    }

    return ret;
}

