/// <summary>
/// Lookup method
/// </summary>
public void lookup()
{
    FieldId stagingFieldId;
    SysDictField sysDictField;

    stagingFieldId = fieldName2Id(common.TableId,DMFSourceXMLToEntityMap_EntityField.valueStr());
    sysDictField = new SysDictField(common.TableId,stagingFieldId);

    this.dataField(0);
    this.performDBLookup(sysDictField.id(), sysDictField.tableid(),curExt());
}

