/// <summary>
/// Click method
/// </summary>
public void clicked()
{
    FormRun     formRun;
    TableId     tableId;
    int         validateStaging;

    super();

    tableId         = element.args().record().TableId;
    fieldName       = element.parmStagingField();
    fieldValue      = element.parmStagingValue();

    validateStaging = ValidateStagingValue.value();

    ISDAppIntgDMFBulkUpdate::updateStagingData(tableId, dmfDefGroupExecution, fieldName, fieldValue, validateStaging);

    //refresh calling form
    formRun = element.args().caller();

    if(formRun)
    {
        formRun.dataSource(1).research(true);
    }

    element.close();
}
